inline const PNV *GetPNV(const void *buf) {
  return ::flatbuffers::GetRoot<PNV>(buf);
}

inline const PNV *GetSizePrefixedPNV(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<PNV>(buf);
}

inline const char *PNVIdentifier() {
  return "$PNV";
}

inline bool PNVBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, PNVIdentifier());
}

inline bool SizePrefixedPNVBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, PNVIdentifier(), true);
}

template <bool B = false>
inline bool VerifyPNVBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<PNV>(PNVIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedPNVBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<PNV>(PNVIdentifier());
}

inline void FinishPNVBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<PNV> root) {
  fbb.Finish(root, PNVIdentifier());
}

inline void FinishSizePrefixedPNVBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<PNV> root) {
  fbb.FinishSizePrefixed(root, PNVIdentifier());
}

inline std::unique_ptr<PNVT> UnPackPNV(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<PNVT>(GetPNV(buf)->UnPack(res));
}

inline std::unique_ptr<PNVT> UnPackSizePrefixedPNV(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<PNVT>(GetSizePrefixedPNV(buf)->UnPack(res));
}

